import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Truck, CheckCircle, XCircle, Eye, MapPin, Phone, Mail, Building2 } from 'lucide-react';
import toast from 'react-hot-toast';
import dispatchService from '../../services/dispatchService';
import DataTable from '../../components/datadisplay/DataTable';
import StatusBadge from '../../components/datadisplay/StatusBadge';
import ConfirmDialog from '../../components/feedback/ConfirmDialog';

const DispatchPartnerManagement = () => {
    const [viewingPartner, setViewingPartner] = useState(null);
    const [verifyConfirm, setVerifyConfirm] = useState(null);
    const queryClient = useQueryClient();

    const { data: partners, isLoading } = useQuery({
        queryKey: ['dispatch-partners'],
        queryFn: () => dispatchService.getPartners()
    });

    const verifyMutation = useMutation({
        mutationFn: (partnerId) => dispatchService.verifyPartner(partnerId),
        onSuccess: () => {
            toast.success('Partner verified successfully');
            queryClient.invalidateQueries(['dispatch-partners']);
            setVerifyConfirm(null);
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Verification failed');
        }
    });

    const columns = [
        {
            key: 'company',
            label: 'Company',
            render: (row) => (
                <div className="flex items-center gap-3">
                    <div className="h-10 w-10 rounded-lg bg-teal-100 dark:bg-teal-900/30 flex items-center justify-center">
                        <Building2 className="h-5 w-5 text-teal-600" />
                    </div>
                    <div>
                        <p className="font-medium text-gray-900 dark:text-white">{row.company_name}</p>
                        <p className="text-xs text-gray-500">{row.contact_person}</p>
                    </div>
                </div>
            )
        },
        {
            key: 'contact',
            label: 'Contact',
            render: (row) => (
                <div className="space-y-1 text-sm">
                    <div className="flex items-center gap-1 text-gray-500">
                        <Mail className="h-3 w-3" />
                        {row.contact_email}
                    </div>
                    <div className="flex items-center gap-1 text-gray-500">
                        <Phone className="h-3 w-3" />
                        {row.contact_phone}
                    </div>
                </div>
            )
        },
        {
            key: 'location',
            label: 'Location',
            render: (row) => (
                <div className="flex items-center gap-1 text-sm text-gray-500">
                    <MapPin className="h-3 w-3" />
                    {row.city}, {row.state}
                </div>
            )
        },
        {
            key: 'vehicle',
            label: 'Vehicle',
            render: (row) => (
                <span className="text-sm">{row.vehicle_type || 'N/A'}</span>
            )
        },
        {
            key: 'status',
            label: 'Status',
            render: (row) => (
                <div className="space-y-1">
                    <StatusBadge
                        status={row.is_verified ? 'active' : 'pending'}
                        label={row.is_verified ? 'Verified' : 'Pending'}
                        size="sm"
                    />
                </div>
            )
        },
        {
            key: 'actions',
            label: 'Actions',
            render: (row) => (
                <div className="flex items-center gap-1">
                    <button
                        onClick={() => setViewingPartner(row)}
                        className="p-2 text-gray-400 hover:text-teal-600 transition-colors"
                        title="View Details"
                    >
                        <Eye className="h-4 w-4" />
                    </button>
                    {!row.is_verified && (
                        <button
                            onClick={() => setVerifyConfirm(row)}
                            className="p-2 text-gray-400 hover:text-emerald-600 transition-colors"
                            title="Verify Partner"
                        >
                            <CheckCircle className="h-4 w-4" />
                        </button>
                    )}
                </div>
            )
        }
    ];

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Dispatch Partners</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Manage dispatch partner accounts and verification
                </p>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <StatCard icon={Truck} label="Total Partners" value={partners?.length || 0} color="teal" />
                <StatCard icon={CheckCircle} label="Verified" value={partners?.filter(p => p.is_verified).length || 0} color="emerald" />
                <StatCard icon={XCircle} label="Pending" value={partners?.filter(p => !p.is_verified).length || 0} color="amber" />
            </div>

            <DataTable
                columns={columns}
                data={partners || []}
                loading={isLoading}
                emptyMessage="No dispatch partners registered yet"
            />

            {/* Partner Details Modal */}
            {viewingPartner && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        className="fixed inset-0 bg-black/50"
                        onClick={() => setViewingPartner(null)}
                    />
                    <motion.div
                        initial={{ scale: 0.95 }}
                        animate={{ scale: 1 }}
                        className="relative bg-white dark:bg-gray-800 rounded-2xl shadow-xl w-full max-w-lg p-6"
                    >
                        <div className="flex items-center justify-between mb-4">
                            <h2 className="text-xl font-bold text-gray-900 dark:text-white">Partner Details</h2>
                            <button onClick={() => setViewingPartner(null)} className="p-1 hover:bg-gray-100 rounded-lg">
                                <XCircle className="h-5 w-5 text-gray-500" />
                            </button>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <p className="text-sm text-gray-500">Company Name</p>
                                <p className="font-medium text-gray-900 dark:text-white">{viewingPartner.company_name}</p>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <p className="text-sm text-gray-500">Contact Person</p>
                                    <p className="font-medium">{viewingPartner.contact_person}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">Phone</p>
                                    <p className="font-medium">{viewingPartner.contact_phone}</p>
                                </div>
                            </div>
                            <div>
                                <p className="text-sm text-gray-500">Email</p>
                                <p className="font-medium">{viewingPartner.contact_email}</p>
                            </div>
                            <div>
                                <p className="text-sm text-gray-500">Address</p>
                                <p className="font-medium">{viewingPartner.address}, {viewingPartner.city}, {viewingPartner.state}</p>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <p className="text-sm text-gray-500">Vehicle Type</p>
                                    <p className="font-medium">{viewingPartner.vehicle_type || 'N/A'}</p>
                                </div>
                                <div>
                                    <p className="text-sm text-gray-500">License Number</p>
                                    <p className="font-medium">{viewingPartner.license_number || 'N/A'}</p>
                                </div>
                            </div>
                        </div>
                    </motion.div>
                </div>
            )}

            <ConfirmDialog
                isOpen={!!verifyConfirm}
                onClose={() => setVerifyConfirm(null)}
                onConfirm={() => verifyMutation.mutate(verifyConfirm.id)}
                title="Verify Partner"
                message={`Verify "${verifyConfirm?.company_name}" as a trusted dispatch partner?`}
                confirmText="Verify"
            />
        </div>
    );
};

const StatCard = ({ icon: Icon, label, value, color }) => {
    const colors = {
        teal: 'bg-teal-100 text-teal-600',
        emerald: 'bg-emerald-100 text-emerald-600',
        amber: 'bg-amber-100 text-amber-600'
    };

    return (
        <div className="bg-white dark:bg-gray-800 rounded-xl p-4 shadow-sm border">
            <div className="flex items-center gap-3">
                <div className={`p-2 rounded-lg ${colors[color]}`}>
                    <Icon className="h-5 w-5" />
                </div>
                <div>
                    <p className="text-sm text-gray-500">{label}</p>
                    <p className="text-xl font-bold">{value}</p>
                </div>
            </div>
        </div>
    );
};

export default DispatchPartnerManagement;
